"Сертификаты получателей": "Recipient certificates",
"🔏 Подпись и шифрование (S/MIME)": "🔏 Signing and encryption (S/MIME)",
"Сертификат ящика с закрытым ключом (.p12 или .pfx — его выдаёт удостоверяющий центр или служба ИБ) позволяет подписывать письма и читать зашифрованные. Ключ хранится на сервере архива зашифрованным. Сертификаты получателей собираются сами из писем с верной подписью.": "A mailbox certificate with a private key (.p12 or .pfx — issued by a certificate authority or the security team) lets you sign messages and read encrypted ones. The key is stored encrypted on the archive server. Recipient certificates are collected automatically from messages with a valid signature.",
"Файл .p12 / .pfx": "File .p12 / .pfx",
"Пароль файла": "File password",
"Выберите файл .p12 или .pfx": "Select a .p12 or .pfx file",
"Сертификат загружен": "Certificate uploaded",
