"Подписывать письма и читать зашифрованные будет нельзя, пока не загрузите сертификат снова.": "You will not be able to sign messages or read encrypted ones until you upload the certificate again.",
"Удалено": "Deleted",
"⬆ Загрузить .cer": "⬆ Upload .cer",
"Сертификаты, загруженные сюда, шифруют только письма из этого ящика. Общий справочник ведёт администратор; сертификаты из писем с доверенной подписью попадают в него сами.": "Certificates uploaded here encrypt only messages from this mailbox. The shared directory is maintained by the administrator; certificates from messages with a trusted signature get there automatically.",
"Сертификат из письма запоминается, только если подпись доверенная и адрес отправителя есть в сертификате; загруженный здесь сертификат письмом не заменяется. Сверяйте отпечаток с владельцем.": "A certificate from a message is remembered only if the signature is trusted and the sender address is in the certificate; a certificate uploaded here is not replaced by one from a message. Check the fingerprint with the owner.",
