"Календарь и адресная книга почтового сервера (Nextcloud, SOGo, Zimbra, Яндекс, Mail.ru, Dovecot с Radicale и другие): контакты сервера попадают в подсказку адресов, ближайшие события видны в окне «📅», принятое приглашение ложится в календарь. Вход — логином и паролем ящика.": "The mail server's calendar and address book (Nextcloud, SOGo, Zimbra, Yandex, Mail.ru, Dovecot with Radicale and others): server contacts appear in address suggestions, upcoming events are shown in the “📅” window, an accepted invitation goes into the calendar. Sign-in uses the mailbox login and password.",
