"📱 Как приложение": "📱 As an app",
"Клиент можно установить как отдельное приложение: в Chrome, Edge и Яндекс Браузере — меню браузера → «Установить приложение» (на телефоне — «Добавить на главный экран»). Тогда он открывается в своём окне, как почтовая программа.": "The client can be installed as a separate app: in Chrome, Edge and Yandex Browser — browser menu → “Install app” (on a phone — “Add to Home screen”). It then opens in its own window, like a mail program.",
