"✔ Правила выполняет почтовый сервер (загружены {}); служба архива их сама не выполняет. Изменили правило — сценарий на сервере обновится сам.": "✔ Rules are run by the mail server (uploaded {}); the archive service does not run them itself. When you change a rule, the script on the server is updated automatically.",
"🖥 Правила на почтовом сервере (Sieve)": "🖥 Rules on the mail server (Sieve)",
"Правила и автоответ можно отдать самому почтовому серверу (Dovecot, Cyrus, Stalwart и другие с ManageSieve): письма будут раскладываться сразу при получении — и в почте на телефоне, даже если служба архива остановлена. Exchange, Gmail и Яндекс Sieve не поддерживают.": "Rules and auto-reply can be handed over to the mail server itself (Dovecot, Cyrus, Stalwart and others with ManageSieve): messages are sorted right on arrival — also in mail on your phone, even if the archive service is stopped. Exchange, Gmail and Yandex do not support Sieve.",
"Выполнять правила и автоответ на почтовом сервере": "Run rules and auto-reply on the mail server",
"Сервер ManageSieve": "ManageSieve server",
"без шифрования (только localhost)": "no encryption (localhost only)",
"Сценарий Sieve, который будет загружен": "Sieve script that will be uploaded",
"Правила загружены на сервер": "Rules uploaded to the server",
"Правила на сервере выключены": "Rules on the server turned off",
"Заменить сценарий на сервере?": "Replace the script on the server?",
"Сценарий клиента станет активным, прежний останется на сервере неактивным.": "The client's script becomes active; the previous one stays on the server inactive.",
"Заменить": "Replace",
"Правила на сервере не обновлены": "Rules on the server were not updated",
