"Проверьте сервер и порт отправки в настройках отправки ящика и доступ к нему из сети архива.": "Check the outgoing server and port in the mailbox sending settings and access to it from the archive network.",
"Неизвестный вид письма: {}.": "Unknown message kind: {}.",
"С этого ящика за последний час отправлено писем на {} адресатов — предел {} в час. Письмо не отправлено.": "Messages to {} recipients were sent from this mailbox in the last hour — the limit is {} per hour. The message was not sent.",
"Подождите или попросите администратора поднять предел (Настройки → Почтовый клиент).": "Wait or ask the administrator to raise the limit (Settings → Mail client).",
