"Порт сервера отправки — число от 1 до 65535.": "The outgoing server port is a number from 1 to 65535.",
"Защита соединения: ssl, starttls или none.": "Connection security: ssl, starttls or none.",
"Вход на сервер отправки: account, custom или none.": "Outgoing server sign-in: account, custom or none.",
"Копия в «Отправленные»: auto, always или never.": "Copy to “Sent”: auto, always or never.",
"Псевдонимов — не больше 20.": "No more than 20 aliases.",
"Ящик копируется входом администратора почтового сервера: пароль администратора на сервер отправки архив не передаёт.": "The mailbox is backed up with the mail server administrator's sign-in: the archive does not pass the administrator password to the outgoing server.",
"Укажите в настройках отправки ящика отдельный вход на сервер отправки или ретранслятор без входа.": "Set a separate outgoing server sign-in or a relay without sign-in in the mailbox sending settings.",
"Сервер отправки {} не принял вход: {}": "The outgoing server {} did not accept the sign-in: {}",
"Проверьте пароль ящика (или вход в настройках отправки). Gmail и Яндекс требуют пароль приложения; в Microsoft 365 у ящика должна быть включена отправка SMTP AUTH, а у приложения OAuth — право SMTP.Send.": "Check the mailbox password (or the sign-in in the sending settings). Gmail and Yandex require an app password; in Microsoft 365 the mailbox must have SMTP AUTH sending enabled, and the OAuth app needs the SMTP.Send permission.",
"Сервер отправки отказался принять адресатов: {}": "The outgoing server refused the recipients: {}",
"Проверьте адреса получателей.": "Check the recipient addresses.",
"Сервер отправки не принял отправителя {}: {}": "The outgoing server did not accept the sender {}: {}",
"Адрес отправителя должен принадлежать ящику (или ящику должно быть разрешено отправлять от этого адреса).": "The sender address must belong to the mailbox (or the mailbox must be allowed to send from this address).",
"Сервер отправки отклонил письмо: {}": "The outgoing server rejected the message: {}",
