"Сервер отправки {}:{} не поддерживает нужную команду: {}": "The outgoing server {}:{} does not support the required command: {}",
"Проверьте защиту соединения в настройках отправки (SSL — порт 465, STARTTLS — 587).": "Check the connection security in the sending settings (SSL — port 465, STARTTLS — 587).",
"Сервер отправки ответил ошибкой: {}": "The outgoing server returned an error: {}",
