"Сервер не принял вход в ящик «{}» меньше минуты назад — повторите позже.": "The server rejected sign-in to mailbox “{}” less than a minute ago — try again later.",
"Частые неудачные входы с адреса архива сервер может заблокировать (fail2ban). Проверьте пароль ящика («Почтовые ящики» → «Проверить»).": "The server may block frequent failed sign-ins from the archive address (fail2ban). Check the mailbox password (“Mailboxes” → “Check”).",
