"Сервер календаря перенаправляет на другой адрес: {}": "The calendar server redirects to another address: {}",
"Если это сервер вашей организации, укажите этот адрес в настройках календаря и контактов — пароль ящика на другой сервер сам не отправляется.": "If this is your organization's server, enter this address in the calendar and contacts settings — the mailbox password is not sent to another server automatically.",
