"Код из приложения сейчас проверить нельзя: секрет двухфакторного входа не расшифровывается.": "The app code cannot be checked right now: the two-factor sign-in secret cannot be decrypted.",
"Так бывает после замены или потери файла secret.key. Войдите резервным кодом либо попросите администратора отключить 2FA командой «mailarchiver reset-2fa -u имя» на сервере.": "This happens after the secret.key file is replaced or lost. Sign in with a recovery code or ask the administrator to turn off 2FA with “mailarchiver reset-2fa -u name” on the server.",
