"Открытые сеансы этого ящика будут завершены. Кто знает его пароль, увидит архив всех ящиков нового владельца — если ящиком пользовался прежний владелец, смените пароль на почтовом сервере.": "Open sessions of this mailbox will be ended. Whoever knows its password will see the archive of all of the new owner's mailboxes — if the previous owner used the mailbox, change the password on the mail server.",
"Загрузка ящиков…": "Loading mailboxes…",
"включён": "enabled",
"копия": "backup",
"копий ещё нет": "no backups yet",
"Ящик и его архив остаются; он просто перестаёт числиться за сотрудником": "The mailbox and its archive remain; it just no longer belongs to the employee",
"Отвязать": "Unlink",
"Ящиков нет — почта сотрудника не копируется.": "No mailboxes — the employee's mail is not backed up.",
"📬 Почтовые ящики сотрудника ({})": "📬 Employee's mailboxes ({})",
"+ Завести ящик": "+ Create mailbox",
"🔗 Привязать существующий": "🔗 Link existing",
"Сотрудник, вошедший паролем любого своего ящика, видит архив всех ящиков из этого списка. Не привязывайте ящик, пароль которого знает кто-то ещё (общий ящик отдела): тот увидит и остальные.": "An employee who signs in with the password of any of their mailboxes sees the archive of all mailboxes in this list. Do not link a mailbox whose password someone else knows (a shared department mailbox): that person will see the others too.",
"Отвязать ящик?": "Unlink the mailbox?",
"Ящик «{}» перестанет числиться за сотрудником «{}». Сам ящик и его архив остаются, синхронизация не заведёт его заново.": "The mailbox “{}” will no longer belong to the employee “{}”. The mailbox itself and its archive remain; synchronization will not create it again.",
"Ящик отвязан": "Mailbox unlinked",
"Завести ящик сотруднику": "Create a mailbox for the employee",
"Адрес ящика": "Mailbox address",
"Ящик заводится по шаблону ящиков сотрудников (сервер, логин, папки, расписание) — обычно выключенным и без пароля. Если ящик с таким логином уже есть, он будет привязан.": "The mailbox is created from the employee mailbox template (server, login, folders, schedule) — usually disabled and without a password. If a mailbox with this login already exists, it will be linked.",
"Завести": "Create",
"Укажите адрес ящика.": "Enter the mailbox address.",
"Ящик заведён": "Mailbox created",
"Этот ящик уже у сотрудника": "This mailbox already belongs to the employee",
