"Перенести": "Transfer",
"Привязать ящик": "Link a mailbox",
"Ящик принадлежит одному сотруднику: ящик, уже числящийся за другим, будет перенесён (с подтверждением).": "A mailbox belongs to one employee: a mailbox already assigned to someone else will be transferred (with confirmation).",
"Привязать": "Link",
"· сейчас:": "· now:",
"Выберите ящик.": "Select a mailbox.",
"{} Перенести его сотруднику «{}»? {}": "{} Transfer it to the employee “{}”? {}",
"Импорт сотрудников из файла": "Import employees from a file",
"Поддерживаются файлы": "Supported files:",
". Первая строка — заголовки столбцов. Распознаются названия: ФИО, E-mail, Должность, Отдел, Телефон, Табельный номер (в любом регистре, принимаются и английские варианты).": ". The first row holds column headers. Recognized names: Full name, Email, Position, Department, Phone, Personnel number (in any case; English variants are accepted too).",
"Сотрудники сопоставляются по табельному номеру, а если его нет — по адресу почты. Уже заведённые карточки обновляются, новые добавляются. Никто не удаляется и не выключается.": "Employees are matched by personnel number, or by email address if there is none. Existing records are updated, new ones are added. Nobody is deleted or disabled.",
