"— по заданию на ящик; одновременно идёт столько копирований, сколько задано в «Одновременных заданий». Быстрее всего.": "— a job per mailbox; as many backups run at once as set in “Concurrent jobs”. The fastest.",
"По очереди, ящик за ящиком": "One by one, mailbox after mailbox",
"— одно задание копирует ящики строго по одному, начиная с тех, что копировались давнее всего. Бережнее к почтовому серверу.": "— a single job backs up mailboxes strictly one at a time, starting with those backed up longest ago. Gentler on the mail server.",
