"Файл с паролями": "Password file",
"Включить ящики после установки пароля": "Enable mailboxes after setting the password",
"Ящик ищется по логину, а если такого логина нет — по адресу сотрудника из справочника. Пароли сохраняются в базе в зашифрованном виде: ни в журнал, ни обратно в интерфейс они не попадают, а загруженный файл удаляется сразу после разбора.": "A mailbox is looked up by login, and if there is no such login — by the employee's address from the directory. Passwords are stored in the database encrypted: they never get into the log or back into the interface, and the uploaded file is deleted right after parsing.",
