"Сервис по очереди войдёт в каждый ящик (IMAP LOGIN) и сразу выйдет — письма не скачиваются. Итог появится в колонке «Вход», а отбор «С неправильным паролем» покажет, какие ящики не смогут копироваться.": "The service will sign in to each mailbox in turn (IMAP LOGIN) and sign out right away — no messages are downloaded. The result appears in the “Sign-in” column, and the “With a wrong password” filter shows which mailboxes cannot be backed up.",
"Какие ящики проверить": "Which mailboxes to check",
