"Только включённые ({})": "Enabled only ({})",
"Каждый неверный пароль — это неудачный вход на почтовом сервере. Если там включена защита от перебора (например fail2ban), большое число неверных паролей подряд может временно заблокировать адрес сервера архива. Проверка идёт не быстрее {} ящиков одновременно — так же, как ночное копирование.": "Every wrong password is a failed sign-in on the mail server. If brute-force protection is enabled there (for example fail2ban), many wrong passwords in a row may temporarily block the archive server's address. The check runs no faster than {} mailboxes at once — just like the nightly backup.",
