"· писем в копии:": "· messages in the backup:",
"({}). Копия инкрементная: каждый прогон докачивает только новые письма, поэтому ниже — даты прогонов и сколько писем каждый добавил.": "({}). Backup is incremental: each run downloads only new messages, so below are the run dates and how many messages each one added.",
"Хранится история последних прогонов (параметр «Хранить записей истории»).": "The history of the latest runs is kept (the “Keep history records” parameter).",
"Неизвестно, есть ли в прежней копии письма, которых нет в новой": "It is unknown whether the previous backup has messages missing from the new one",
"не сравнивалась": "not compared",
"Тот же Message-ID, тема, отправитель и дата, но другие байты: сервер пересобрал заголовки того же письма": "Same Message-ID, subject, sender and date, but different bytes: the server rebuilt the headers of the same message",
"другой вариант: {}": "another variant: {}",
"Есть только здесь, но старше срока хранения ящика ({} дн.) — ночная очистка удалила бы их из архива и так": "Present only here, but older than the mailbox retention period ({} days) — the nightly cleanup would remove them from the archive anyway",
"старше срока хранения: {}": "older than the retention period: {}",
"Этих писем нет в новой копии: удалены на сервере, лежат в исключённых или неоткрывающихся папках либо больше лимита размера": "These messages are not in the new backup: deleted on the server, located in excluded or unopenable folders, or larger than the size limit",
"только здесь: {} · {}": "only here: {} · {}",
"всё есть в новой копии": "everything is in the new backup",
"Файлы не прочитались (нет ключа шифрования или файл повреждён)": "Files could not be read (no encryption key or the file is damaged)",
"не прочитано: {}": "not read: {}",
"из папок, которые сейчас не открываются на сервере: {} — вернутся, когда папки снова начнут копироваться": "from folders that do not open on the server now: {} — they will return when the folders are backed up again",
"новая копия после «с нуля» ещё не прочитала все папки — вернуть письма можно после полного копирования": "the new backup after the fresh start has not read all folders yet — messages can be returned after a full backup",
"· возвращено в архив: {}": "· returned to the archive: {}",
"есть в новой:": "present in the new one:",
"сравнено {}": "compared {}",
"После копии «с нуля» копирование ещё не прочитало все папки ящика — иначе письма непрочитанных папок попали бы в архив дважды": "After a fresh backup, backup has not read all folders of the mailbox yet — otherwise messages of the unread folders would get into the archive twice",
"disabled title=\"После копии «с нуля» копирование ещё не прочитало все папки ящика — иначе письма непрочитанных папок попали бы в архив дважды\"": "disabled title=\"After a fresh backup, backup has not read all folders of the mailbox yet — otherwise messages of the unread folders would get into the archive twice\"",
