"задание №{}": "job #{}",
". Итог появится здесь.": ". The result will appear here.",
"Прежние копии: {}": "Previous backups: {}",
"При пересоздании копии «с нуля» прежние письма не удаляются, а переносятся в карантин. Письма, которых на сервере уже нет, остаются только здесь.": "When a backup is recreated from scratch, the previous messages are not deleted but moved to quarantine. Messages that are no longer on the server remain only here.",
"покажет, есть ли такие;": "will show whether there are any;",
"🛟 Вернуть": "🛟 Return",
"запишет их в архив ящика (в те же папки) — после этого карантин можно удалить без потерь.": "will write them to the mailbox archive (into the same folders) — after that the quarantine can be deleted without loss.",
"Прежняя копия": "Previous backup",
"Размер": "Size",
"Сравнение с новой копией": "Comparison with the new backup",
"Карантинных копий нет — на диске только актуальная копия.": "There are no quarantined backups — only the current backup is on disk.",
"Задание уже идёт": "The job is already running",
"Возврат писем запущен": "Returning messages started",
"Сравнение запущено": "Comparison started",
"Задание №{}. Итог появится в «Прежних копиях».": "Job #{}. The result will appear in “Previous backups”.",
"Вернуть письма в архив?": "Return the messages to the archive?",
"Писем, которых нет в новой копии: {}. Они будут записаны в архив ящика — в те же папки — и станут видны в просмотре, поиске и выгрузке. Письма старше срока хранения ящика не возвращаются (их удалила бы ночная очистка).": "Messages missing from the new backup: {}. They will be written to the mailbox archive — into the same folders — and become visible in viewing, search and export. Messages older than the mailbox retention period are not returned (the nightly cleanup would delete them).",
"Прежняя копия НЕ сравнивалась с новой: неизвестно, есть ли в ней письма, которых нет в новой копии. Надёжнее сначала нажать «Сравнить».": "The previous backup has NOT been compared with the new one: it is unknown whether it contains messages missing from the new backup. It is safer to click “Compare” first.",
"Есть письма, которых нет в новой копии": "There are messages missing from the new backup",
"{}. Эти письма будут потеряны.": "{}. These messages will be lost.",
"Удалить карантинную копию?": "Delete the quarantined backup?",
"Удалить прежнюю копию с потерей писем?": "Delete the previous backup and lose messages?",
"Каталог с прежними письмами будет удалён безвозвратно (фоновым заданием).": "The directory with the previous messages will be deleted permanently (by a background job).",
"Удалить с потерей писем": "Delete and lose messages",
"Удаление поставлено в очередь": "Deletion queued",
"Задание №{}.": "Job #{}.",
"Скопировать заново: {}": "Back up again: {}",
"Архив этого ящика удерживается — «с нуля» его не пересоздать, пока действует удержание.": "The archive of this mailbox is held — it cannot be recreated from scratch while the hold is in effect.",
"Полностью с нуля": "Completely from scratch",
"Прежняя копия ящика уходит в карантин («Прежние копии»), индекс очищается, и всё скачивается с сервера заново.": "The previous backup of the mailbox goes to quarantine (“Previous backups”), the index is cleared, and everything is downloaded from the server again.",
"Осторожно с режимом «с нуля».": "Be careful with the “from scratch” mode.",
"Письма, которых уже нет на почтовом сервере, останутся только в карантине: в просмотре, поиске и экспорте их не будет, а после удаления карантина их не вернуть. Выбирайте его, только если архив испорчен и нужен именно чистый лист. {}": "Messages that are no longer on the mail server will remain only in quarantine: they will not appear in viewing, search or export, and after the quarantine is deleted they cannot be recovered. Choose it only if the archive is damaged and you really need a clean slate. {}",
"Копию «с нуля» запускает администратор.": "A fresh backup is started by the administrator.",
"Обычная копия скачивает только те письма, которых ещё нет в архиве. Здесь можно перепроверить архив целиком.": "A normal backup downloads only messages that are not yet in the archive. Here you can recheck the whole archive.",
"Докачать потерянные письма": "Download lost messages",
"Сверяет индекс с файлами на диске: если файл письма пропал (сбой диска, оборванный прогон, чужая уборка), письмо скачивается заново.": "Compares the index with the files on disk: if a message file is missing (disk failure, interrupted run, someone else's cleanup), the message is downloaded again.",
"Ничего не удаляется": "Nothing is deleted",
"— это безопасный режим.": "— this is a safe mode.",
"Скопировать ящик заново с нуля?": "Back up the mailbox again from scratch?",
"Прежняя копия ящика «{}» уйдёт в карантин, а письма будут заново скачаны с сервера.": "The previous backup of the mailbox “{}” will go to quarantine, and the messages will be downloaded from the server again.",
"Письма, которых на сервере уже нет, останутся только в карантине. Продолжить?": "Messages that are no longer on the server will remain only in quarantine. Continue?",
