"Посчитать заново": "Recalculate",
"Идёт подсчёт…": "Calculating…",
"▶ Посчитать": "▶ Calculate",
"🧬 Одинаковые вложения": "🧬 Duplicate attachments",
"— сколько места освободится, если хранить одну копию": "— how much space would be freed by keeping a single copy",
"Рассылки всем сотрудникам, логотипы в подписях, пересланные по цепочке договоры лежат в каждом письме отдельной копией. Отчёт читает письма и находит вложения с одинаковым содержимым (имя файла может отличаться).": "Mailings to all employees, logos in signatures, contracts forwarded along a chain are stored as a separate copy in every message. The report reads the messages and finds attachments with identical content (the file name may differ).",
"Формат хранения не меняется": "The storage format does not change",
"— это только подсчёт.": "— this is only a calculation.",
"Посчитать заново?": "Recalculate?",
"Прочитанное забудется, и весь архив будет прочитан снова — на большом архиве это часы (копирования ящиков при этом идут своим чередом).": "What was read will be forgotten and the whole archive will be read again — on a large archive this takes hours (mailbox backups keep running as usual).",
"Подсчёт запущен": "Calculation started",
"Уже выполняется": "Already running",
"Письма читаются в фоне; отчёт обновится здесь сам.": "Messages are read in the background; the report will update here by itself.",
"Прочитано писем: {} из {} ({}%) · учтено вложений: {}. Большой архив читается частями — между ними идут копирования ящиков.": "Messages read: {} of {} ({}%) · attachments counted: {}. A large archive is read in parts — mailbox backups run in between.",
"Отчёт ещё не считался. Нажмите «Посчитать»: первый подсчёт читает весь архив (на большом архиве — часы), следующие — только новые письма.": "The report has not been calculated yet. Click “Calculate”: the first calculation reads the whole archive (hours on a large archive), the following ones — only new messages.",
"⏳ Прочитано {}% писем ({} из {}) — цифры вырастут, когда подсчёт дойдёт до конца.": "⏳ {}% of messages read ({} of {}) — the figures will grow when the calculation reaches the end.",
"С момента отчёта в архив добавилось писем: {} — нажмите «Обновить», чтобы учесть их (прочитаются только новые).": "Messages added to the archive since the report: {} — click “Refresh” to include them (only new ones will be read).",
"Если хранить вложения отдельно от писем и без кодировки base64 (она увеличивает файлы примерно на треть), освободится до": "If attachments were stored separately from messages and without base64 encoding (it makes files about a third larger), up to",
"({}% архива).": "({}% of the archive) would be freed.",
"Сжатие копии включено — на диске экономия будет примерно на четверть меньше указанной.": "Backup compression is on — the savings on disk will be about a quarter less than shown.",
"Писем-двойников целиком: {} ({}) — одно и то же письмо лежит в нескольких папках; их вложения уже учтены выше.": "Whole duplicate messages: {} ({}) — the same message is stored in several folders; their attachments are already counted above.",
"Не удалось прочитать писем: {} (подробности — в событиях задания в разделе «Задания»).": "Messages that could not be read: {} (details are in the job events in the “Jobs” section).",
"Вложения меньше {} не учитываются. Отчёт от {}.": "Attachments smaller than {} are not counted. Report of {}.",
