"Почтовый сервер не подключён — доступны действия по IMAP с ящиками архива. Учётные записи сервера (вход, пароли, квоты, псевдонимы, автоответ) появятся, когда вы подключите сервер в разделе «Почтовые серверы» (Microsoft 365, Google Workspace, Яндекс 360, Zimbra, Kerio…) или настроите Axigen («Настройки → Сервер Axigen»).": "No mail server is connected — IMAP actions with archive mailboxes are available. Server accounts (sign-in, passwords, quotas, aliases, auto-reply) will appear when you connect a server in the “Mail servers” section (Microsoft 365, Google Workspace, Yandex 360, Zimbra, Kerio…) or configure Axigen (“Settings → Axigen server”).",
