"Изменения на подключённых серверах не разрешены — доступны чтение, отчёты и действия по IMAP. Разрешить можно в карточке подключения («Почтовые серверы» → «Изменить»).": "Changes on the connected servers are not allowed — reading, reports and IMAP actions are available. They can be allowed in the connection card (“Mail servers” → “Edit”).",
"Изменения учётных записей Axigen выключены — действия, которые их меняют, недоступны. Включите «Разрешить изменения на сервере» в «Настройки → Сервер Axigen».": "Changes to Axigen accounts are turned off — actions that change them are unavailable. Turn on “Allow changes on the server” in “Settings → Axigen server”.",
"Сверки с Axigen ещё не было — нажмите «Сверить с Axigen», чтобы увидеть учётные записи сервера.": "There has been no reconciliation with Axigen yet — click “Reconcile with Axigen” to see the server accounts.",
"⚙️ Идёт действие с ящиками на сервере: {}. Новое встанет в очередь за ним.": "⚙️ An action with mailboxes on the server is running: {}. A new one will be queued after it.",
