"Сначала — проверка: что будет с каждой строкой. Учётные записи создаются заданием, по одной; пароли — случайные (файлом для раздачи сотрудникам) или один общий временный.": "First — a check: what will happen to each line. Accounts are created by a job, one at a time; passwords are random (as a file to hand out to employees) or one shared temporary password.",
