"Действие удаляет письма с сервера. Для подтверждения введите число ящиков в расписании:": "The action deletes messages from the server. To confirm, enter the number of mailboxes in the schedule:",
"Сам MailArchiver почтовый сервер не меняет — расписание вы включаете сами, для этого действия и этих ящиков. При каждом запуске условия проверяются заново по каждому ящику (полный архив, свежая копия, сверка писем), итог — в «Истории» раздела. В расписании — именно эти {} {}: новые ящики сами в него не попадут.": "MailArchiver itself does not change the mail server — you turn the schedule on yourself, for this action and these mailboxes. On every run the conditions are checked again for each mailbox (full archive, fresh backup, message reconciliation); the result is in the section's “History”. The schedule includes exactly these {} {}: new mailboxes do not get into it by themselves.",
