"Время": "Time",
"По часовому поясу расписаний («Настройки → Планировщик»). Лучше ночью, когда ящиками почти не пользуются.": "In the schedules time zone (“Settings → Scheduler”). Better at night, when mailboxes are hardly used.",
"Разрешаю выполнять «{}» для {} {} по расписанию, без проверки перед каждым запуском. Кто и когда разрешил — запишется в журнал.": "I allow running “{}” for {} {} on schedule, without a check before each run. Who allowed it and when will be written to the log.",
"Создать расписание": "Create schedule",
"⚠️ Сейчас ни один из ящиков не подходит — запуски будут их пропускать, пока не выполнятся условия (причины — выше).": "⚠️ None of the mailboxes is suitable now — runs will skip them until the conditions are met (the reasons are above).",
"Если бы запуск был сейчас:": "If the run were now:",
"⚠️ Планировщик выключен («Настройки → Планировщик»): расписание сохранится, но запускаться не будет, пока его не включить.": "⚠️ The scheduler is off (“Settings → Scheduler”): the schedule will be saved but will not run until it is turned on.",
"Сохраняем…": "Saving…",
"Расписание создано": "Schedule created",
"Действия по расписанию": "Scheduled actions",
"Создаются только вами: на вкладке «Ящики и действия» выберите ящики и действие (очистить корзину или спам, удалить или перенести старые письма, отчёт) и нажмите «🕑 По расписанию…». Каждый запуск — обычное задание: условия проверяются заново, итог — в «Истории» (кто — «расписание №…»).": "Created only by you: on the “Mailboxes and actions” tab select mailboxes and an action (empty trash or spam, delete or move old messages, report) and click “🕑 On schedule…”. Each run is an ordinary job: the conditions are checked again, the result is in “History” (who — “schedule #…”).",
"⚠️ Планировщик выключен («Настройки → Планировщик») — расписания не запускаются.": "⚠️ The scheduler is off (“Settings → Scheduler”) — schedules do not run.",
