". Пароль можно не указывать — такой ящик заведётся выключенным, а пароли загрузите потом файлом («Загрузить пароли»). Подойдут и две колонки, скопированные из Excel, и строки вида «Иванов Иван <ivanov@company.ru>;пароль». Если адрес есть в справочнике сотрудников, ящик получит ФИО и сразу свяжется с карточкой.": ". The password may be omitted — such a mailbox is created disabled, and you can upload passwords later as a file (“Upload passwords”). Two columns copied from Excel work too, as do lines like “John Smith <smith@company.com>;password”. If the address is in the employee directory, the mailbox gets the full name and is linked to the employee record right away.",
"Список ящиков": "Mailbox list",
