"Для каждого включённого ящика прежняя локальная копия будет перенесена в": "For each enabled mailbox the previous local backup will be moved to",
"карантин": "quarantine",
"(«Прежние копии»), а все письма — скачаны с почтового сервера заново.": "(“Previous backups”), and all messages will be downloaded from the mail server again.",
"Письма, которых на сервере уже нет, останутся только в карантине: в просмотре, поиске и экспорте их не будет.": "Messages that are no longer on the server will remain only in quarantine: they will not appear in viewing, search or export.",
"Карантин занимает место на диске, пока вы его не удалите (Групповые действия → «Удалить прежние копии»).": "Quarantine takes disk space until you delete it (Bulk actions → “Delete previous backups”).",
"Все письма скачиваются заново — это долго и нагружает почтовый сервер; ящики идут через общую очередь.": "All messages are downloaded again — this takes a long time and loads the mail server; mailboxes go through the common queue.",
"Ящики с удержанием архива, выключенные и без пароля пропускаются.": "Mailboxes with an archive hold, disabled ones and ones without a password are skipped.",
"Если нужно лишь вернуть пропавшие файлы, безопаснее «Докачать потерянные письма» — ничего не удаляется.": "If you only need to bring back missing files, “Download lost messages” is safer — nothing is deleted.",
