"Логин {}": "Login {}",
"Письма берёт администратор Axigen через службу FTP Backup («Настройки → Сервер Axigen») — пароль сотрудника не нужен. Логин — полный адрес. Пароль ниже необязателен: он нужен только для восстановления по IMAP и входа сотрудника в архив.": "Messages are taken by the Axigen administrator through the FTP Backup service (“Settings → Axigen server”) — the employee's password is not needed. The login is the full address. The password below is optional: it is needed only for restore via IMAP and for the employee's sign-in to the archive.",
"Подключение": "Connection",
"— загружается… —": "— loading… —",
"В ящик входит само подключение (токен приложения или администратор почты) — пароль сотрудника не нужен. Сервер, порт и шифрование подставляются из подключения.": "The connection itself signs in to the mailbox (an application token or the mail administrator) — the employee's password is not needed. Server, port and encryption are taken from the connection.",
