"Копии старше срока удаляются ежедневно (на письма на сервере не влияет). Свой срок в днях задаётся в меню ящика → «Хранение копий».": "Backups older than the period are deleted daily (does not affect messages on the server). A custom period in days is set in the mailbox menu → “Backup retention”.",
