"Архив удерживается открытым делом (раздел «Дела»): письма не удаляются, пока дело не закрыто": "The archive is held by an open case (the “Cases” section): messages are not deleted until the case is closed",
"🔒 по делу": "🔒 by case",
"(архив уволенного сотрудника)": "(archive of a dismissed employee)",
"Письма ящика не удаляются по сроку хранения{}": "The mailbox's messages are not deleted by the retention period{}",
"Срок удержания архива прошёл — архив можно удалить (меню ящика)": "The archive hold period has passed — the archive can be deleted (mailbox menu)",
"удержание истекло": "hold expired",
