"Открыть раздел «Дела»": "Open the “Cases” section",
"Архив ящика удерживается": "The mailbox archive is held",
"открытым делом": "by an open case",
": письма не удаляются ни по сроку хранения, ни вручную. Удержание снимается, когда дело закрывают или убирают из него ящик.": ": messages are deleted neither by the retention period nor manually. The hold is removed when the case is closed or the mailbox is removed from it.",
"Сейчас архив удерживается потому, что сотрудник уволен.": "The archive is currently held because the employee is dismissed.",
"Пока действует удержание, письма ящика": "While the hold is in effect, the mailbox's messages",
"не удаляются": "are not deleted",
"очисткой по сроку хранения — даже если у ящика срок «3 дня». Удобно для архива уволенного сотрудника, проверок и споров.{}": "by the retention cleanup — even if the mailbox period is “3 days”. Useful for the archive of a dismissed employee, audits and disputes.{}",
"Удерживать до": "Hold until",
"Бессрочно": "Indefinitely",
