"⛔ Будут удалены ящик, его настройки, индекс и": "⛔ The mailbox, its settings, the index and",
"все файлы писем на диске": "all message files on disk",
"(писем: {}, {}). Это необратимо; письма, которых уже нет на почтовом сервере, не восстановить. Копия вне сервера удалит их у себя при следующем прогоне.": "(messages: {}, {}) will be deleted. This is irreversible; messages that are no longer on the mail server cannot be recovered. The off-site copy will delete them on its side at the next run.",
"Для подтверждения введите название ящика:": "To confirm, enter the mailbox name:",
"Удалить навсегда": "Delete permanently",
"Файлов писем удалено: {} ({})": "Message files deleted: {} ({})",
"глобальная настройка": "global setting",
"хранить всё (бессрочно)": "keep everything (indefinitely)",
"последние {} дн.": "last {} days",
"Хранение копий: {}": "Backup retention: {}",
"Отсеяно по сроку хранения:": "Filtered out by the retention period:",
"{} — копирование их не скачивает (они старше срока) или очистка уже удалила их из архива, а на почтовом сервере они ещё лежат.": "{} — backup does not download them (they are older than the period) or the cleanup has already removed them from the archive, while they are still on the mail server.",
"Забыть отсеянные письма": "Forget filtered-out messages",
"Следующее копирование заново проверит даты этих писем на сервере: моложе срока — скачаются, старше — снова будут пропущены. Нужно, если часы сервера архива уходили вперёд или у писем на почтовом сервере были неверные даты.": "The next backup will recheck the dates of these messages on the server: younger than the period — they will be downloaded, older — skipped again. Needed if the archive server's clock ran ahead or the messages on the mail server had wrong dates.",
"напр. 30": "e.g. 30",
"Сколько дней хранить": "How many days to keep",
"локальные копии": "local backups",
"писем этого ящика от текущей даты. Копии старше выбранного срока будут автоматически удаляться (ежедневная очистка). На письма на самом сервере это не влияет.": "of this mailbox's messages from the current date. Backups older than the selected period will be deleted automatically (daily cleanup). Messages on the server itself are not affected.",
