"Через FTP Backup Axigen — без пароля ящика (без отметок «прочитано» и «важное»)": "Via Axigen FTP Backup — without the mailbox password (without the “read” and “flagged” marks)",
"По IMAP с паролем ящика{}": "Via IMAP with the mailbox password{}",
"Через FTP Backup письма заливает администратор Axigen: нужно «Разрешить изменения на сервере» в настройках Axigen. В конце MailArchiver проверяет, что сервер показывает залитые письма.": "Via FTP Backup the messages are uploaded by the Axigen administrator: “Allow changes on the server” must be on in the Axigen settings. At the end MailArchiver checks that the server shows the uploaded messages.",
"♻️ Восстановление заливает письма из локальной копии обратно на IMAP-сервер.": "♻️ Restore uploads messages from the local backup back to the IMAP server.",
"Рекомендуется сначала сделать пробный прогон, а заливать — в папку с префиксом, чтобы не смешивать с текущей почтой.": "It is recommended to do a trial run first, and to upload into a folder with a prefix so as not to mix with current mail.",
