"Укажите префикс папки — иначе письма попадут прямо в рабочие папки ящика.": "Specify a folder prefix — otherwise the messages will go straight into the mailbox's working folders.",
"Укажите имя папки назначения.": "Specify the target folder name.",
"Залить в ИСХОДНЫЕ папки?": "Upload into the ORIGINAL folders?",
"Письма из архива будут добавлены прямо в рабочие папки ящика «{}». Отменить это нельзя.": "Messages from the archive will be added straight into the working folders of the mailbox “{}”. This cannot be undone.",
"Пробный прогон": "Trial run",
"Заливка на сервер": "Upload to the server",
"Импорт .pst: {}": "Import .pst: {}",
"пусто — папки как в файле": "empty — folders as in the file",
"Письма из файла Outlook (.pst или .ost) переносятся в ящик — на почтовый сервер или сразу в локальную копию. Файл разбирает сам MailArchiver: внешние программы не нужны. Переносятся папки, письма с вложениями, флаги («прочитано», «отвечено», «помечено») и даты получения; контакты, календарь и задачи пропускаются.": "Messages from an Outlook file (.pst or .ost) are moved to the mailbox — to the mail server or straight into the local backup. MailArchiver parses the file itself: no external programs are needed. Folders, messages with attachments, flags (“read”, “answered”, “flagged”) and received dates are transferred; contacts, calendar and tasks are skipped.",
"Откуда взять файл {}": "Where to take the file from {}",
