"В локальную копию ящика (архив)": "To the mailbox's local backup (archive)",
"Письма будут записаны только в архив MailArchiver: на почтовый сервер ничего не заливается. Письма старше срока хранения ящика не записываются — если импортируете старый архив, сначала поставьте архив ящика на удержание или задайте «хранить всё».": "Messages will be written only to the MailArchiver archive: nothing is uploaded to the mail server. Messages older than the mailbox retention period are not written — if you import an old archive, first put the mailbox archive on hold or set “keep everything”.",
