"Учтите: служба под systemd не видит каталоги": "Note: the systemd service does not see the directories",
"(в её unit-файле ProtectHome=true и PrivateTmp=true) — что бы ни лежало там и какие бы права ни стояли, для службы там пусто или закрыто. Держите файлы в другом месте, например в": "(its unit file has ProtectHome=true and PrivateTmp=true) — whatever lies there and whatever permissions are set, for the service it is empty or closed. Keep files elsewhere, for example in",
