"Сейчас каталог импорта — ссылка на {}, а там лежат и файлы самой службы. Направьте ссылку на отдельный каталог, где будут только файлы .pst и .ost: {}.": "The import directory is currently a link to {}, and the service's own files are there too. Point the link to a separate directory with only .pst and .ost files: {}.",
"Параметр": "The parameter",
"в config.yaml направляет временные файлы службы в каталог импорта: задайте для них другой каталог (или уберите параметр) и перезапустите службу.": "in config.yaml points the service's temporary files into the import directory: set another directory for them (or remove the parameter) and restart the service.",
"Пересоздайте ссылку так, чтобы она вела на настоящий каталог: куда ведёт каждая, покажет": "Recreate the link so that it leads to a real directory: where each one leads is shown by",
