"🖥️ Ящики на сервере": "🖥️ Server mailboxes",
"➕ Подключить сервер": "➕ Connect a server",
"Через подключение к API почтового сервера MailArchiver сверяет учётные записи с архивом, следит за сервером и — если разрешить изменения — выполняет действия раздела «Ящики на сервере»: закрыть вход, пароли, ФИО, псевдонимы, квоты, автоответ, пересылку, удаление при полном архиве. Серверов можно подключить несколько (например, Axigen и Microsoft 365 на время переезда).": "Through a connection to the mail server's API, MailArchiver reconciles accounts with the archive, monitors the server and — if changes are allowed — performs the actions of the “Server mailboxes” section: close sign-in, passwords, full names, aliases, quotas, auto-reply, forwarding, deletion when the archive is complete. Several servers can be connected (for example, Axigen and Microsoft 365 during a migration).",
"Какой сервер подключить?": "Which server to connect?",
"Сервер Axigen настраивается отдельно — «Настройки → Сервер Axigen».": "The Axigen server is configured separately — “Settings → Axigen server”.",
