"Чего этот сервер через API не позволяет": "What this server does not allow via the API",
"Ящик копируется через подключение — без пароля сотрудника; настройки (срок хранения, папки) — из шаблона ящиков сотрудников.": "The mailbox is backed up via the connection — without the employee's password; settings (retention period, folders) come from the employee mailbox template.",
"Этот сервер не пускает в ящики без паролей — ящики заводятся вручную, с паролем.": "This server does not let in to mailboxes without passwords — mailboxes are created manually, with a password.",
"Название подключения": "Connection name",
"Подключение включено": "Connection enabled",
"Разрешить изменения на сервере": "Allow changes on the server",
"Без этого — только чтение: сверка, отчёты, слежение. С ним в «Ящиках на сервере» доступны действия, которые меняют учётные записи (закрыть вход, пароли, удаление при полном архиве…). Каждое действие сначала показывает проверку.": "Without this — read only: reconciliation, reports, monitoring. With it, “Server mailboxes” offers actions that change accounts (close sign-in, passwords, deletion when the archive is complete…). Each action first shows a check.",
"Сверять учётные записи по расписанию": "Reconcile accounts on schedule",
