": следующий ящик начинается, когда закончен предыдущий. Сначала — ящики, которые копировались давнее всего, поэтому незаконченный проход в следующий раз продолжится с тех, до кого очередь не дошла. Выключенные ящики и ящики без пароля пропускаются.": ": the next mailbox starts when the previous one is finished. Mailboxes backed up longest ago go first, so an unfinished pass will continue next time with those that were not reached. Disabled mailboxes and mailboxes without a password are skipped.",
