"Пока нет: служба сохраняет настройки раз в сутки и перед каждым восстановлением.": "None yet: the service saves the settings once a day and before every restore.",
"Пароль копий настроек не задан: ежедневные копии шифруются ключом secret.key и в копию вне сервера не уходят. Задайте его в разделе «🗄 Копия настроек» ниже на этой странице.": "The settings backup password is not set: daily copies are encrypted with the secret.key key and do not go to the off-site copy. Set it in the “🗄 Settings backup” section below on this page.",
"Ежедневная копия настроек выключена (раздел «🗄 Копия настроек»).": "The daily settings backup is turned off (the “🗄 Settings backup” section).",
"Копия настроек": "Settings backup",
"⬇ Скачать копию": "⬇ Download backup",
"Все настройки одним файлом: параметры раздела «Настройки», подключения к почтовым серверам, сотрудники, ящики с расписаниями и доступом к чужим ящикам, личные настройки почтового клиента (подписи, правила, автоответ, метки, шаблоны, адресная книга, сертификаты). Писем и истории в копии нет — для них снимки базы и копия вне сервера.": "All settings in one file: the parameters of the “Settings” section, mail server connections, employees, mailboxes with schedules and access to other mailboxes, personal mail client settings (signatures, rules, auto-reply, labels, templates, address book, certificates). There are no messages or history in the backup — for them there are database snapshots and the off-site copy.",
"Защитить паролем": "Protect with a password",
"С паролем в копии всё: и пароли ящиков, подключений и уведомлений, пользователи интерфейса с API-токенами, ключи S/MIME, файл config.yaml.": "With a password the backup contains everything: passwords of mailboxes, connections and notifications, interface users with API tokens, S/MIME keys, the config.yaml file.",
"Пароль копии (не короче {} символов)": "Backup password (at least {} characters)",
"Ещё раз": "Once more",
"Без пароля в файл не попадут секреты и учётные записи: после восстановления пароли ящиков и подключений придётся ввести заново.": "Without a password, secrets and user accounts do not get into the file: after restoring, the passwords of mailboxes and connections will have to be entered again.",
"Разделы": "Sections",
"⬆ Восстановить из копии": "⬆ Restore from a backup",
"Ничего не удаляется. Сначала покажем, что изменится; перед восстановлением служба сама сохранит нынешние настройки — к ним можно вернуться ниже.": "Nothing is deleted. First we show what will change; before restoring, the service itself saves the current settings — you can return to them below.",
