"scrape_configs: - job_name: mailarchiver metrics_path: /metrics scheme: {} authorization: credentials: ТОКЕН static_configs: - targets: ['{}'] # Пример правила тревоги: ящик не копировался больше 3 суток - alert: MailArchiverStaleMailbox expr: mailarchiver_account_enabled == 1 and time() - mailarchiver_account_last_backup_timestamp_seconds > 259200 for: 1h": "scrape_configs: - job_name: mailarchiver metrics_path: /metrics scheme: {} authorization: credentials: TOKEN static_configs: - targets: ['{}'] # Example alert rule: a mailbox has not been backed up for more than 3 days - alert: MailArchiverStaleMailbox expr: mailarchiver_account_enabled == 1 and time() - mailarchiver_account_last_backup_timestamp_seconds > 259200 for: 1h",
