"всё: ящики, письма, настройки, пользователи, удаление": "everything: mailboxes, messages, settings, users, deletion",
"следит за копированием и запускает его: копия ящиков, «Докачать потерянные», проверки входа, папок и целостности, отмена и повтор этих заданий, журнал. Писем не читает, настроек не меняет, ничего не удаляет и не выгружает": "monitors backup and starts it: mailbox backup, “Download lost messages”, sign-in, folder and integrity checks, cancelling and retrying these jobs, the log. Does not read messages, does not change settings, deletes and exports nothing",
