"＋ Новое дело": "＋ New case",
"Дело собирает переписку для проверки, спора или запроса: ящики сотрудников, период и поисковый запрос. Пока дело открыто, архив его ящиков удерживается — письма не удаляются ни по сроку хранения, ни вручную. Найденные письма выгружаются в ZIP с описью и контрольными суммами SHA-256.": "A case collects correspondence for an audit, a dispute or a request: employees' mailboxes, a period and a search query. While the case is open, the archive of its mailboxes is held — messages are deleted neither by the retention period nor manually. The found messages are exported to a ZIP with a manifest and SHA-256 checksums.",
