"{} писем ({}). В архив попадут опись с SHA-256 каждого письма, подпись описи ключом сервера и отчёт. Выгрузка идёт заданием очереди; скачивание файла попадёт в аудит.": "{} messages ({}). The archive will contain a manifest with the SHA-256 of each message, the manifest signed with the server key, and a report. The export runs as a queue job; downloading the file gets into the audit log.",
"EML — письма ровно в том виде, в каком хранятся в архиве (для экспертизы)": "EML — messages exactly as they are stored in the archive (for forensic examination)",
"PST — один файл для Outlook (письма преобразуются; суммы — по исходным письмам)": "PST — one file for Outlook (messages are converted; checksums — of the original messages)",
