"Пароль нигде не сохраняется — передайте его получателю отдельно. Архив открывают 7-Zip, WinRAR, WinZip, Keka (встроенные средства Windows и macOS — нет).": "The password is stored nowhere — give it to the recipient separately. The archive opens in 7-Zip, WinRAR, WinZip, Keka (the built-in tools of Windows and macOS cannot).",
