"Задание #{}. Когда оно закончится, нажмите «↻ Обновить».": "Job #{}. When it finishes, click “↻ Refresh”.",
"🔏 Ключ подписи выгрузок": "🔏 Export signing key",
"Опись каждой выгрузки дела (manifest.csv) подписывается этим ключом (Ed25519). Сообщите отпечаток получателям выгрузок заранее, по другому каналу: совпадение отпечатка в отчёте выгрузки с этим доказывает, что опись сформировал ваш архив и её не меняли.": "The manifest of each case export (manifest.csv) is signed with this key (Ed25519). Tell the export recipients the fingerprint in advance, via another channel: a match of the fingerprint in the export report with this one proves that the manifest was produced by your archive and was not changed.",
"Проверка (OpenSSL 3):": "Verification (OpenSSL 3):",
"⬇ Скачать signing_key.pem": "⬇ Download signing_key.pem",
