"Добавить ящики в дело": "Add mailboxes to the case",
"Добавлено ящиков: {}": "Mailboxes added: {}",
"Закрыть дело?": "Close the case?",
"Удержание архива по этому делу будет снято: ящикам вернётся удержание, которое было до дела (если их не держит другое открытое дело). Выгрузки и история сохранятся.": "The archive hold for this case will be removed: the mailboxes get back the hold they had before the case (unless another open case holds them). Exports and history are kept.",
"Дело закрыто": "Case closed",
"Дело открыто": "Case reopened",
"Удалить дело?": "Delete the case?",
"Дело, его выгрузки (файлы ZIP) и состав ящиков будут удалены. Записи аудита останутся. Письма в архиве не удаляются.": "The case, its exports (ZIP files) and its mailbox list will be deleted. Audit records remain. Messages in the archive are not deleted.",
"Дело удалено": "Case deleted",
