"Неизвестный режим восстановления «{}».": "Unknown restore mode “{}”.",
"Допустимо: original, single, prefixed.": "Allowed: original, single, prefixed.",
"Укажите префикс папок — иначе письма попадут прямо в рабочие папки ящика.": "Specify a folder prefix — otherwise the messages will go straight into the mailbox's working folders.",
"Например «Восстановлено». Для заливки в исходные папки выберите режим «в исходные папки».": "For example “Restored”. To upload into the original folders, choose the “into the original folders” mode.",
