"При обходе всех пользователей doveadm отдаёт ошибку, если споткнулся хотя бы на одном; кто именно — видно в журнале Dovecot. Обходу нужна итерация базы пользователей (iterate_query в SQL).": "When going over all users, doveadm returns an error if it stumbled on at least one; which one is shown in the Dovecot log. Going over needs iteration of the user database (iterate_query in SQL).",
