"зашифрованные утверждения не поддерживаются — выключите шифрование утверждений для архива у поставщика (ответ всё равно идёт по https)": "encrypted assertions are not supported — turn off assertion encryption for the archive at the provider (the response goes over https anyway)",
"в ответе должно быть ровно одно утверждение": "the response must contain exactly one assertion",
"подписан не ответ и не утверждение": "neither the response nor the assertion is signed",
"нет ответа поставщика (SAMLResponse)": "no provider response (SAMLResponse)",
"ответ адресован не архиву: {}": "the response is not addressed to the archive: {}",
"издатель «{}» не тот, что в настройках («{}»)": "the issuer “{}” is not the one in the settings (“{}”)",
"в утверждении нет условий (Conditions)": "the assertion has no conditions (Conditions)",
"утверждение ещё не действует (часы сервера или поставщика спешат?)": "the assertion is not valid yet (is the server's or the provider's clock fast?)",
"срок утверждения истёк": "the assertion has expired",
"утверждение выдано не архиву (Audience: {}); идентификатор архива у поставщика — {}": "the assertion was not issued to the archive (Audience: {}); the archive identifier at the provider is {}",
"нет подтверждения субъекта для этого адреса возврата ({}) или его срок истёк": "there is no subject confirmation for this return address ({}) or it has expired",
"вход, начатый поставщиком (без InResponseTo), не принимается — входите кнопкой на странице архива": "a provider-initiated sign-in (without InResponseTo) is not accepted — sign in with the button on the archive page",
"в утверждении нет сведений о входе (AuthnStatement)": "the assertion has no sign-in information (AuthnStatement)",
"это утверждение уже использовано (повтор ответа)": "this assertion has already been used (response replay)",
"поставщик передал одноразовый NameID (transient): по нему не узнать пользователя при следующем входе. Настройте у поставщика постоянный NameID (persistent или адрес почты) или укажите «Атрибут имени пользователя»": "the provider passed a one-time NameID (transient): it cannot identify the user at the next sign-in. Configure a persistent NameID at the provider (persistent or the email address) or specify the “User name attribute”",
"поставщик не передал имя пользователя{}": "the provider did not pass the user name{}",
"вход устарел или уже использован — начните заново": "the sign-in is outdated or already used — start again",
"вход начат не в этом браузере или устарел (нет cookie состояния)": "the sign-in was started in another browser or is outdated (no state cookie)",
"ответ поставщика — на чужой запрос входа (InResponseTo не совпадает)": "the provider response is to someone else's sign-in request (InResponseTo does not match)",
