"сертификат поставщика не читается (нужен X.509 в PEM или base64)": "the provider certificate cannot be read (X.509 in PEM or base64 is needed)",
"в описании несколько поставщиков — укажите «Идентификатор поставщика»": "the description has several providers — specify the “Provider identifier”",
