"Диагностика": "Diagnostics",
"Очередь писем": "Mail queue",
"Проверка подключения{}": "Connection check{}",
"через FTP Backup Axigen": "via Axigen FTP Backup",
"через подключение к почтовому серверу": "via the mail server connection",
"пароль верный": "the password is correct",
"Дать почтовому серверу передышку между ящиками. 0 — без паузы.": "Give the mail server a breather between mailboxes. 0 — no pause.",
"Прежние копии остаются на диске, пока вы не удалите карантин, — новая копия займёт столько же места ещё раз. Если место кончится, копирование ящиков остановится само.": "Previous backups stay on disk until you delete the quarantine — the new backup will take the same amount of space once more. If space runs out, mailbox backup will stop by itself.",
"0 — все ящики в одно время. Например, 120: запуски равномерно распределятся с 02:00 до 04:00.": "0 — all mailboxes at the same time. For example, 120: runs will be spread evenly from 02:00 to 04:00.",
"Спам Корзина": "Spam Trash",
"Выключите, чтобы удалить и несравнённые прежние копии, и те, где есть письма, которых нет в новой копии, — такие письма будут потеряны.": "Turn it off to delete both unreconciled previous backups and those that contain messages missing from the new backup — such messages will be lost.",
"INBOX Отправленные": "INBOX Sent",
"нет такого файла или каталога": "no such file or directory",
"на пути к нему лежит файл, а не каталог": "a file, not a directory, is on the path to it",
"ссылки указывают друг на друга (слишком много переходов по ссылкам)": "links point to each other (too many link hops)",
"нет прав": "no permission",
"операция не разрешена": "operation not permitted",
"файловая система доступна только для чтения": "the file system is read-only",
"на диске нет места": "no space left on the disk",
"Если данные лежат на отдельном диске — проверьте, что он подключён (findmnt, lsblk, mount -a), и запустите службу снова. Если каталог данных переносили — найдите его (find / -name mailarchiver.db) и направьте ссылку туда: sudo ln -sfn НАСТОЯЩИЙ_КАТАЛОГ ПУТЬ_ИЗ_НАСТРОЕК. Каталог по ссылке не создавайте: служба начала бы работу с пустой базой.": "If the data is on a separate disk, check that it is connected (findmnt, lsblk, mount -a) and start the service again. If the data directory was moved, find it (find / -name mailarchiver.db) and point the link there: sudo ln -sfn REAL_DIRECTORY PATH_FROM_SETTINGS. Do not create the directory behind the link: the service would start working with an empty database.",
"Задание числилось выполняющимся, но очередь его не выполняла (сбой учёта) — возвращено в очередь (попытка не засчитана).": "The job was listed as running, but the queue was not running it (accounting failure) — returned to the queue (the attempt is not counted).",
