"через подключение": "via the connection",
"Параметры (раздел «Настройки»)": "Parameters (the “Settings” section)",
"Подключения к почтовым серверам": "Mail server connections",
"Ящики, их расписания и доступ к чужим ящикам": "Mailboxes, their schedules and access to other mailboxes",
"Пользователи и API-токены": "Users and API tokens",
"Личные настройки почтового клиента": "Personal mail client settings",
"Файл config.yaml": "The config.yaml file",
"не указан ящик": "no mailbox specified",
"общее расписание привязано к ящику": "a shared schedule is bound to a mailbox",
"не разбирается ({})": "cannot be parsed ({})",
"Слишком много неверных кодов для этой учётной записи — ввод кодов из приложения заблокирован на {} мин.": "Too many wrong codes for this account — code entry from the app is blocked for {} min.",
"Слишком много неверных кодов для этой учётной записи за сутки — ввод кодов из приложения заблокирован до конца суток.": "Too many wrong codes for this account in a day — code entry from the app is blocked until the end of the day.",
"Почтовый клиент выключен («Настройки → Почтовый клиент»): «Почта» показывает только архив.": "The mail client is turned off (“Settings → Mail client”): “Mail” shows only the archive.",
"Ящик «{}» выключен — письма из архива можно читать, а менять ящик на сервере нельзя.": "The mailbox “{}” is turned off — messages from the archive can be read, but the mailbox on the server cannot be changed.",
"Пароль ящика «{}» не расшифровывается текущим ключом — введите его заново в карточке ящика.": "The password of the mailbox “{}” cannot be decrypted with the current key — enter it again in the mailbox card.",
"Ящик «{}» копируется через FTP Backup Axigen без пароля — войти в него по IMAP нельзя. Задайте ящику пароль, чтобы работать с ним в клиенте.": "The mailbox “{}” is backed up via Axigen FTP Backup without a password — it cannot be signed in to via IMAP. Set a password for the mailbox to work with it in the client.",
"Администратору писать письма и менять ящики сотрудников запрещено настройкой «Администратор может писать и менять ящики» («Настройки → Почтовый клиент»).": "The administrator is forbidden to write messages and change employees' mailboxes by the setting “The administrator can write and change mailboxes” (“Settings → Mail client”).",
"Ящик «{}» открыт вам только для чтения: писать от его имени и менять его на сервере нельзя (доступ даёт администратор).": "The mailbox “{}” is open to you read-only: you cannot write on its behalf or change it on the server (access is granted by the administrator).",
"Ящик копируется входом администратора почты: своего пароля у архива нет. Для отправки укажите в настройках отправки отдельный вход на сервер отправки (или ретранслятор без входа).": "The mailbox is backed up with the mail administrator sign-in: the archive has no password of its own. For sending, specify a separate sign-in to the sending server in the sending settings (or a relay without sign-in).",
"У ящика не известен адрес отправителя: логин не похож на адрес, у сотрудника адреса нет. Укажите адрес в настройках отправки ящика.": "The mailbox's sender address is unknown: the login does not look like an address, and the employee has no address. Specify the address in the mailbox's sending settings.",
"Не указан сервер отправки (SMTP) — заполните настройки отправки ящика.": "The sending server (SMTP) is not specified — fill in the mailbox's sending settings.",
"У ящика нет токена OAuth2 — переподключите ящик.": "The mailbox has no OAuth2 token — reconnect the mailbox.",
